"""Small wire-format and diagnostic primitives for the server."""
import os
import struct
import time


class ServerExit(Exception):
    def __init__(self, message, status=1):
        self.message = message
        self.status = status
        super().__init__(message)


def log(message):
    # The daemon's diagnostics have a fixed English timestamp independent of locale.
    t = time.localtime()
    months = ('Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec')
    stamp = f'{months[t.tm_mon-1]} {t.tm_mday:02d} {t.tm_hour:02d}:{t.tm_min:02d}:{t.tm_sec:02d}'
    text = f'[{os.getpid()}] {stamp} {message}\n'
    try:
        os.write(2, text.encode('utf-8', 'surrogateescape'))
    except OSError:
        pass


def fatal(message, status=1):
    raise ServerExit(message, status)


def u32(n):
    return struct.pack('>I', n & 0xffffffff)


def string(value):
    if isinstance(value, str):
        value = value.encode('utf-8', 'surrogateescape')
    return u32(len(value)) + value


def mpint(n):
    if n == 0:
        return u32(0)
    data = n.to_bytes((n.bit_length() + 7)//8, 'big')
    if data[0] & 0x80:
        data = b'\0' + data
    return string(data)


def text(b):
    return b.decode('utf-8', 'surrogateescape')


class Reader:
    def __init__(self, data):
        self.data = data
        self.pos = 0

    def remaining(self):
        return len(self.data) - self.pos

    def get(self, n):
        if n < 0 or self.pos + n > len(self.data):
            fatal('Bad buf_getptr')
        result = self.data[self.pos:self.pos+n]
        self.pos += n
        return result

    def byte(self):
        return self.get(1)[0]

    def uint(self):
        return struct.unpack('>I', self.get(4))[0]

    def string(self):
        n = self.uint()
        if n > 4096:
            fatal('String too long')
        return self.get(n)

    def bigstring(self):
        return self.get(self.uint())

    def integer(self):
        data = self.string()
        if data and data[0] & 0x80:
            raise ValueError('negative mpint')
        return int.from_bytes(data, 'big')
