    for i in range(254, -1, -1):
        bit = (scalar >> i) & 1
        if swap ^ bit:
            x2, x3 = x3, x2
            z2, z3 = z3, z2
        swap = bit
        a, b = (x2 + z2) % p, (x2 - z2) % p
        aa, bb = a*a % p, b*b % p
        e = (aa - bb) % p
        c, d = (x3 + z3) % p, (x3 - z3) % p
        da, cb = d*a % p, c*b % p
        x3 = (da + cb)**2 % p
        z3 = x * (da - cb)**2 % p
        x2 = aa * bb % p
        z2 = e * (aa + 121665*e) % p
    if swap:
        x2, x3 = x3, x2
        z2, z3 = z3, z2
    return (x2 * pow(z2, p-2, p) % p).to_bytes(32, 'little')


