import select
import signal
import socket
import sys
import time

from common import ServerExit, fatal, log


def stop(signum, frame):
    fatal('Terminated by signal', 0)


def install_signals():
    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    signal.signal(signal.SIGPIPE, signal.SIG_IGN)


def listeners(options):
    sockets = []
    for address, port in options.ports:
        try:
            infos = socket.getaddrinfo(address, port, socket.AF_UNSPEC, socket.SOCK_STREAM, 0, socket.AI_PASSIVE)
        except (socket.gaierror, UnicodeError) as e:
            reason = e.strerror if isinstance(e, OSError) else 'Name or service not known'
            log(f"Failed listening on '{port}': Error resolving: {reason}")
            continue
        bound = []
        last_error = 'Address already in use'
        seen = set()
        for family, socktype, proto, canon, addr in infos:
            marker = (family, addr)
            if marker in seen:
                continue
            seen.add(marker)
            sock = None
            try:
                sock = socket.socket(family, socktype, proto)
                sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                if family == socket.AF_INET6:
                    sock.setsockopt(socket.IPPROTO_IPV6, socket.IPV6_V6ONLY, 1)
                if options.interface is not None:
                    try:
                        sock.setsockopt(socket.SOL_SOCKET, socket.SO_BINDTODEVICE,
                                        os.fsencode(options.interface)+b'\0')
                    except OSError:
                        log("Couldn't set SO_BINDTODEVICE")
                sock.bind(addr)
                sock.listen(20)
                bound.append(sock)
            except OSError as e:
                last_error = e.strerror
                if sock is not None:
                    sock.close()
        if not bound:
            log(f"Failed listening on '{port}': Error listening: {last_error}")
        sockets.extend(bound)
    if not sockets:
        fatal('No listening ports available.')
    return sockets


def connection(sock, options, keys, from_inetd=False):
    from session import Session
    try:
        address = sock.getpeername()
        if not isinstance(address, tuple) or len(address) < 2:
            fatal('Failed socket address: Address family not supported by protocol')
    except OSError as e:
        fatal('Failed socket address: '+e.strerror)
    host, port = address[:2]
    remote = f'{host}:{port}'
    if options.childpipe is None:
        log('Child connection from '+remote)
    session = Session(sock, options, keys, remote)
    status = 0
    reason = 'Exited normally'
    try:
        session.run()
    except ServerExit as e:
        status, reason = e.status, e.message
    except (ConnectionError, BrokenPipeError, EOFError):
        pass
    except OSError as e:
        if e.errno not in (errno.ECONNRESET, errno.EPIPE, errno.EBADF):
            reason = e.strerror or 'Exited normally'
            status = 1
    except (ValueError, IndexError, OverflowError):
        reason, status = 'Bad buf_getptr', 1
    session.finish(reason)
    sock.close()
    return status


def serve(options, keys):
    install_signals()
    if 'i' in options.flags:
        try:
            sock = socket.socket(fileno=os.dup(0))
            sock.getpeername()
        except OSError as e:
            fatal('Failed socket address: '+e.strerror)
        return connection(sock, options, keys, True)
    sockets = listeners(options)
    if 'F' not in options.flags:
        pid = os.fork()
        if pid:
            return 0
        os.setsid()
        os.chdir('/')
        try:
            fd = os.open('/dev/null', os.O_RDWR)
            os.dup2(fd, 0)
            os.dup2(fd, 1)
            if fd > 2:
                os.close(fd)
        except OSError:
            pass
        log('Running in background')
    else:
        log('Not backgrounding')
    try:
        with open(options.pidfile, 'w') as f:
            f.write(str(os.getpid())+'\n')
    except OSError:
        pass
    children = {}
    try:
        while True:
            # Reap without a SIGCHLD callback, avoiding races around fork().
            for pid in list(children):
                try:
                    found, _ = os.waitpid(pid, os.WNOHANG)
                    if found:
                        del children[pid]
                except ChildProcessError:
                    del children[pid]
            readable, _, _ = select.select(sockets, [], [], .3)
            for listener in readable:
                try:
                    sock, addr = listener.accept()
                except OSError:
                    continue
                host = addr[0]
                # The admission limit protects unauthenticated sessions.
                if len(children) >= 30 or sum(x == host for x in children.values()) >= 5:
                    sock.close()
                    continue
                try:
                    pid = os.fork()
                except OSError:
                    sock.close()
                    continue
                if pid == 0:
                    for s in sockets:
                        s.close()
                    code = 0
                    try:
                        code = connection(sock, options, keys)
                    except ServerExit as e:
                        log('Early exit: '+e.message)
                        code = e.status
                    os._exit(code)
                children[pid] = host
                sock.close()
    except ServerExit as e:
        log('Early exit: '+e.message)
        return e.status
    finally:
        for sock in sockets:
            sock.close()
        try:
            os.unlink(options.pidfile)
        except OSError:
            pass
