#!/usr/bin/env python3
"""Standalone entry point."""
import os
import sys
from common import ServerExit, log
from options import Options


def main():
    try:
        options = Options(sys.argv)
        # Loading the protocol code is unnecessary for help and argument errors.
        from keys import HostKeys
        keys = HostKeys(options)
        from daemon import serve
        return serve(options, keys)
    except ServerExit as e:
        log('Early exit: '+e.message)
        return e.status


if __name__ == '__main__':
    sys.exit(main())
