def fail_open(session, remote, reason=1, message=''):
    session.send(92,u32(remote)+u32(reason)+string(message)+string(''))


def open_channel(session, r):
    kind = text(r.string())
    remote, window, maximum = r.uint(), r.uint(), r.uint()
    if kind not in ('session', 'direct-tcpip', 'direct-streamlocal@openssh.com'):
        fail_open(session, remote, 3, 'Unknown channel type')
        return
    if len(session.channels) >= 10:
        fail_open(session, remote, 4, 'Too many channels')
        return
    local = session.next_channel
    session.next_channel += 1
    ch = Channel(session, local, remote, window, maximum, kind)
    if kind == 'direct-tcpip':
        host, port = text(r.string()), r.uint()
        r.string();r.uint()
        if 'j' in session.options.flags or 'no-port-forwarding' in session.auth_options or 'restrict' in session.auth_options:
            fail_open(session,remote)
            return
        try:
            ch.stream = socket.create_connection((host,port),timeout=10)
            ch.stream.settimeout(None)
        except OSError as e:
            fail_open(session,remote,2,'Connect failed')
            return
    elif kind == 'direct-streamlocal@openssh.com':
        if 'j' in session.options.flags or 'u' in session.options.flags:
            fail_open(session,remote)
            return
        path = text(r.string())
        try:
            ch.stream = socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
            ch.stream.connect(path)
        except OSError:
            fail_open(session,remote,2,'Connect failed')
            return
    session.channels[local] = ch
    session.send(91,u32(remote)+u32(local)+u32(session.options.window)+u32(32768))


def channel_request(session, r):
    local = r.uint()
    ch = session.channels.get(local)
    if ch is None:
        fatal('Unknown channel')
    name, want = text(r.string()), r.byte()
    ok = False
    if name == 'pty-req' and not ch.process and ch.pty_master is None:
        ch.term = text(r.string())
        cols, rows = r.uint(),r.uint()
        r.uint();r.uint();r.bigstring()
        if 'no-pty' not in session.auth_options and 'restrict' not in session.auth_options:
            ch.pty_master,ch.pty_slave = pty.openpty()
            ch.window_change(cols,rows)
            ok = True
    elif name == 'window-change':
        cols, rows = r.uint(),r.uint()
        ch.window_change(cols,rows)
        ok = True
    elif name == 'env':
        key,value = text(r.string()),text(r.string())
        if key in ('LANG','LANGUAGE') or key.startswith('LC_'):
            ch.env[key] = value
            ok = True
    elif name in ('exec','shell') and ch.process is None and ch.kind == 'session':
        command = text(r.bigstring()) if name == 'exec' else None
        ok = ch.start(command)
    elif name == 'subsystem' and ch.process is None:
        subsystem = text(r.string())
        if subsystem == 'sftp':
            ok = ch.start('/usr/libexec/sftp-server')
    elif name == 'signal' and ch.process is not None:
        signame = text(r.string())
        signum = getattr(signal,'SIG'+signame,None)
        if signum:
