    t = packet[0]
    r = Reader(packet[1:])
    if t == 90:
        open_channel(session,r)
    elif t == 98:
        channel_request(session,r)
    elif t == 80:
        global_request(session,r)
    elif t in (81,82):
        session.keepalive_count = 0
    elif t == 20:
        session.make_kex()
        session.wire.send_packet(session.server_kex)
        session.key_exchange(packet)
    elif t in (91,92,93,94,95,96,97,99,100):
        local = r.uint()
        ch = session.channels.get(local)
        if ch is None:
            fatal('Unknown channel')
        if t == 93:
            ch.window += r.uint()
        elif t in (94,95):
            if t == 95:
                r.uint()
