            os.setsid()
            if self.pty_slave is not None:
                try:
                    fcntl.ioctl(0, termios.TIOCSCTTY, 0)
                except OSError:
                    pass
            if os.geteuid() == 0:
                os.initgroups(pw.pw_name,pw.pw_gid)
                os.setgid(pw.pw_gid)
                os.setuid(pw.pw_uid)
        try:
            if self.pty_master is not None:
                env['SSH_TTY'] = os.ttyname(self.pty_slave)
                self.process = subprocess.Popen(args,executable=shell,stdin=self.pty_slave,stdout=self.pty_slave,
                    stderr=self.pty_slave,cwd=pw.pw_dir,env=env,preexec_fn=child_setup)
                os.close(self.pty_slave)
                self.pty_slave = None
            else:
                self.process = subprocess.Popen(args,executable=shell,stdin=subprocess.PIPE,stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,cwd=pw.pw_dir,env=env,preexec_fn=child_setup)
                self.input,self.output,self.error = self.process.stdin,self.process.stdout,self.process.stderr
        except OSError:
            return False
        return True

    def send_data(self, data, stderr=False):
        while data and self.window > 0:
            n = min(len(data), self.window, max(1, self.maximum), 32768)
            piece, data = data[:n], data[n:]
            if stderr:
                self.session.send(95, u32(self.remote)+u32(1)+string(piece))
            else:
                self.session.send(94, u32(self.remote)+string(piece))
