    session.send(92,u32(remote)+u32(reason)+string(message)+string(''))


def open_channel(session, r):
    kind = text(r.string())
    remote, window, maximum = r.uint(), r.uint(), r.uint()
    if kind not in ('session', 'direct-tcpip', 'direct-streamlocal@openssh.com'):
        fail_open(session, remote, 3, 'Unknown channel type')
        return
    if len(session.channels) >= 10:
        fail_open(session, remote, 4, 'Too many channels')
        return
    local = session.next_channel
    session.next_channel += 1
    ch = Channel(session, local, remote, window, maximum, kind)
    if kind == 'direct-tcpip':
        host, port = text(r.string()), r.uint()
        r.string();r.uint()
        if 'j' in session.options.flags or 'no-port-forwarding' in session.auth_options or 'restrict' in session.auth_options:
            fail_open(session,remote)
            return
        try:
            ch.stream = socket.create_connection((host,port),timeout=10)
            ch.stream.settimeout(None)
        except OSError as e:
            fail_open(session,remote,2,'Connect failed')
            return
    elif kind == 'direct-streamlocal@openssh.com':
        if 'j' in session.options.flags or 'u' in session.options.flags:
            fail_open(session,remote)
            return
        path = text(r.string())
        try:
            ch.stream = socket.socket(socket.AF_UNIX,socket.SOCK_STREAM)
            ch.stream.connect(path)
        except OSError:
            fail_open(session,remote,2,'Connect failed')
            return
    session.channels[local] = ch
    session.send(91,u32(remote)+u32(local)+u32(session.options.window)+u32(32768))


def channel_request(session, r):
    local = r.uint()
    ch = session.channels.get(local)
    if ch is None:
        fatal('Unknown channel')
    name, want = text(r.string()), r.byte()
    ok = False
    if name == 'pty-req' and not ch.process and ch.pty_master is None:
        ch.term = text(r.string())
        cols, rows = r.uint(),r.uint()
        r.uint();r.uint();r.bigstring()
        if 'no-pty' not in session.auth_options and 'restrict' not in session.auth_options:
            ch.pty_master,ch.pty_slave = pty.openpty()
            ch.window_change(cols,rows)
            ok = True
    elif name == 'window-change':
        cols, rows = r.uint(),r.uint()
        ch.window_change(cols,rows)
        ok = True
    elif name == 'env':
        key,value = text(r.string()),text(r.string())
        if key in ('LANG','LANGUAGE') or key.startswith('LC_'):
            ch.env[key] = value
            ok = True
    elif name in ('exec','shell') and ch.process is None and ch.kind == 'session':
        command = text(r.bigstring()) if name == 'exec' else None
        ok = ch.start(command)
    elif name == 'subsystem' and ch.process is None:
        subsystem = text(r.string())
        if subsystem == 'sftp':
            ok = ch.start('/usr/libexec/sftp-server')
    elif name == 'signal' and ch.process is not None:
        signame = text(r.string())
        signum = getattr(signal,'SIG'+signame,None)
        if signum:
            try:
                os.killpg(ch.process.pid, signum)
                ok = True
            except OSError:
                pass
    if want:
        session.send(99 if ok else 100,u32(ch.remote))


def global_request(session,r):
    name, want = text(r.string()),r.byte()
    ok = False
    result = b''
    if name in ('tcpip-forward','cancel-tcpip-forward'):
        address,port = text(r.string()),r.uint()
        key = (address,port)
        if name == 'cancel-tcpip-forward':
            sock = session.listeners.pop(key,None)
            if sock:
                sock.close()
                ok = True
        elif 'k' not in session.options.flags and 'no-port-forwarding' not in session.auth_options and 'restrict' not in session.auth_options:
            bindaddr = address
            if 'a' not in session.options.flags:
                bindaddr = '127.0.0.1'
            elif address in ('','*'):
                bindaddr = '0.0.0.0'
            try:
                sock = socket.socket(socket.AF_INET6 if ':' in bindaddr else socket.AF_INET,socket.SOCK_STREAM)
                sock.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1)
                sock.bind((bindaddr,port));sock.listen(16)
                actual = sock.getsockname()[1]
                session.listeners[(address,actual)] = sock
                ok = True
                if port == 0:
                    result = u32(actual)
            except OSError:
                pass
    if want:
        session.send(81 if ok else 82,result if ok else b'')


def dispatch(session,packet):
    t = packet[0]
    r = Reader(packet[1:])
    if t == 90:
        open_channel(session,r)
    elif t == 98:
        channel_request(session,r)
    elif t == 80:
        global_request(session,r)
    elif t in (81,82):
        session.keepalive_count = 0
    elif t == 20:
        session.make_kex()
        session.wire.send_packet(session.server_kex)
        session.key_exchange(packet)
    elif t in (91,92,93,94,95,96,97,99,100):
        local = r.uint()
        ch = session.channels.get(local)
        if ch is None:
            fatal('Unknown channel')
        if t == 93:
            ch.window += r.uint()
        elif t in (94,95):
            if t == 95:
                r.uint()
            data = r.bigstring()
            try:
                if ch.stream:
                    ch.stream.sendall(data)
                elif ch.pty_master is not None:
                    os.write(ch.pty_master,data)
                elif ch.input and not ch.input_closed:
                    ch.input.write(data);ch.input.flush()
            except OSError:
                pass
            session.send(93,u32(ch.remote)+u32(len(data)))
        elif t == 96:
            if ch.stream:
                try:
                    ch.stream.shutdown(socket.SHUT_WR)
                except OSError:
                    pass
            elif ch.input:
                ch.input.close()
                ch.input_closed = True
        elif t == 97:
            if not ch.closed:
                session.send(97,u32(ch.remote))
            ch.cleanup()
            del session.channels[local]
        elif t == 91:
            ch.remote,ch.window,ch.maximum = r.uint(),r.uint(),r.uint()
        elif t == 92:
            ch.cleanup()
            del session.channels[local]
    else:
        session.send(3,u32(session.wire.in_seq-1))


def channel_loop(session):
    while True:
        watches = {session.sock:None}
        for ch in session.channels.values():
            if ch.closed or ch.window <= 0:
                continue
            for fd,kind in [(ch.output,False),(ch.error,True),(ch.stream,False),(ch.pty_master,False)]:
                if fd is not None:
                    watches[fd] = (ch,kind)
        for key,sock in session.listeners.items():
            watches[sock] = key
        if session.wire.received:
            ready = [session.sock]
        else:
            ready,_,_ = select.select(list(watches),[],[],.15)
        now = time.monotonic()
        for fd in ready:
            action = watches[fd]
            if fd is session.sock:
                packet = session.read()
                session.last_activity = now
                session.keepalive_count = 0
                dispatch(session,packet)
            elif isinstance(action,tuple) and action and isinstance(action[0],str):
                address,port = action
                stream,peer = fd.accept()
                local = session.next_channel;session.next_channel += 1
                ch = Channel(session,local,0,0,32768,'forwarded-tcpip')
                ch.stream = stream
                session.channels[local] = ch
                session.send(90,string('forwarded-tcpip')+u32(local)+u32(session.options.window)+u32(32768)+
                             string(address)+u32(port)+string(peer[0])+u32(peer[1]))
            else:
                ch,is_error = action
                fileno = fd if isinstance(fd,int) else fd.fileno()
                try:
                    data = os.read(fileno,min(32768,ch.window,ch.maximum or 32768))
                except OSError as e:
                    data = b''
                if data:
                    session.last_activity = now
                    ch.send_data(data,is_error)
                else:
                    if fd == ch.pty_master:
                        os.close(ch.pty_master);ch.pty_master = None
                    elif fd is ch.stream:
                        ch.stream.close();ch.stream = None
                    else:
                        fd.close()
                        if fd is ch.output:
                            ch.output = None
                        if fd is ch.error:
                            ch.error = None
        for ch in list(session.channels.values()):
            done = ch.process is not None and ch.process.poll() is not None and ch.output is None and ch.error is None and ch.pty_master is None
            if ch.kind != 'session' and ch.stream is None:
                done = True
            if done and not ch.closed:
                if ch.process is not None:
                    code = ch.process.returncode
                    if code >= 0:
                        session.send(98,u32(ch.remote)+string('exit-status')+b'\0'+u32(code))
                    else:
                        sig = signal.Signals(-code).name[3:]
                        session.send(98,u32(ch.remote)+string('exit-signal')+b'\0'+string(sig)+b'\0'+string('')+string(''))
                session.send(96,u32(ch.remote))
                session.send(97,u32(ch.remote))
                ch.closed = True
        if session.options.idle and now-session.last_activity >= session.options.idle:
            fatal('Idle timeout')
        if session.options.keepalive and now-max(session.wire.last_sent,session.wire.last_received) >= session.options.keepalive:
            if session.keepalive_count >= 3:
                fatal('Keepalive timeout')
            session.send(80,string('keepalive@openssh.com')+b'\1')
            session.keepalive_count += 1
