/* Native, self-contained launcher for this program's own Python modules.
 * No reference executable or external SSH implementation is used.
 */
#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <unistd.h>

#include "payload.h"

static void fail(const char *operation) {
    fprintf(stderr, "%s: %s\n", operation, strerror(errno));
    exit(1);
}

int main(int argc, char **argv) {
    int fd = memfd_create("server-modules", 0);
    if (fd < 0) fail("Creating program image");
    size_t done = 0;
    while (done < sizeof(application_data)) {
        ssize_t n = write(fd, application_data + done, sizeof(application_data) - done);
        if (n < 0 && errno == EINTR) continue;
        if (n <= 0) fail("Writing program image");
        done += (size_t)n;
    }
    if (lseek(fd, 0, SEEK_SET) < 0) fail("Seeking program image");
    /* Keep low descriptor numbers free for sockets and inetd's optional pipe. */
    int high = fcntl(fd, F_DUPFD, 64);
    if (high >= 0) {
        close(fd);
        fd = high;
    }
    char image[64];
    snprintf(image, sizeof(image), "/proc/self/fd/%d", fd);
    char **args = calloc((size_t)argc + 5, sizeof(*args));
    if (!args) fail("Allocating arguments");
    args[0] = "/usr/bin/python3";
    args[1] = "-I";
    args[2] = image;
    args[3] = argc ? argv[0] : "";
    for (int i = 1; i < argc; ++i) args[i + 3] = argv[i];
    args[argc + 3] = NULL;
    execv(args[0], args);
    fail("Starting Python runtime");
    return 1;
}
